// === Backfill AD-HOC de contacts (janela por data) ===
// Cole seu token e ajuste a janela:
const TOKEN = "Bearer pat-na1-PASTE_SEU_TOKEN_AQUI";   // <-- token HubSpot
const DAYS  = 60;                                       // <-- janela em dias (ex.: 60)

const CUTOFF = Date.now() - DAYS*24*3600*1000;
const props = ["firstname","lastname","email","lifecyclestage","createdate","lastmodifieddate",
  "hs_analytics_source","hs_analytics_source_data_1","hs_analytics_source_data_2",
  "hs_v2_date_entered_lead","hs_v2_date_entered_marketingqualifiedlead",
  "hs_v2_date_entered_salesqualifiedlead","hs_v2_date_entered_opportunity","hs_v2_date_entered_customer"];

let after = null;
const out = [];
for (let page = 0; page < 100; page++) {          // trava de segurança: 100 páginas (10k)
  const body = {
    filterGroups: [{ filters: [{ propertyName: "createdate", operator: "GTE", value: String(CUTOFF) }] }],
    sorts: [{ propertyName: "createdate", direction: "ASCENDING" }],
    properties: props,
    limit: 100
  };
  if (after) body.after = after;
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: "https://api.hubapi.com/crm/v3/objects/contacts/search",
    headers: { Authorization: TOKEN, "Content-Type": "application/json" },
    body, json: true
  });
  for (const it of (res.results || [])) {
    out.push({ json: {
      Contact_ID: it.id,
      hs_lastmodifieddate: it.properties?.lastmodifieddate ?? null,
      _synced_at: new Date().toISOString(),
      _raw: JSON.stringify({ properties: it.properties })
    }});
  }
  after = res.paging && res.paging.next ? res.paging.next.after : null;
  if (!after) break;
}
return out;
